import { test, expect } from '@playwright/test';

test.describe('Tab Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should update URL hash when the first tab is clicked', async ({ page }) => {
    await page.getByRole('tab', { name: 'Tab 1' }).click();
    expect(page.url()).toContain('#tab1');
  });

  test('should update URL hash when the second tab is clicked', async ({ page }) => {
    await page.getByRole('tab', { name: 'Tab 2' }).click();
    expect(page.url()).toContain('#tab2');
  });
});
